import { createHash } from "node:crypto";
test("PDF X and VT neutral retain official typed profiles and required raw graph references",async()=>{
  const profile=Array.from(new Uint8Array(await Bun.file(new URL("../../../🪶️sqlite/🧫️fixtures/🌈️x-vt-initial/🌈️sRGB2014.icc",import.meta.url)).arrayBuffer()));
  expect(profile.length).toBe(3024);expect(createHash("sha256").update(new Uint8Array(profile)).digest("hex")).toBe("384b832de3412066743b52a75ee906b6fb9fb8d9e09e936fc2c43223815c6e0a");
  const ref=(num:number)=>({kind:"ref" as const,num,gen:0}),name=(value:string)=>({kind:"name" as const,value});
  for(const subset of ["🖨️x","🧾️vt"]){
    const fixture=JSON.parse(await Bun.file(new URL(`../../../🪶️sqlite/🧫️fixtures/🌈️x-vt-initial/${subset}.json`,import.meta.url)).text()),schema=JSON.parse(await Bun.file(new URL(`../../../🪶️sqlite/🧫️fixtures/🌈️x-vt-initial/${subset}.schema.json`,import.meta.url)).text()),validate=new Ajv2020({strict:true}).compile(schema);
    expect(validate(fixture)).toBe(true);expect(validate({...fixture,unexpected:true})).toBe(false);expect(validate({...fixture,profile:{...fixture.profile,components:4}})).toBe(false);
    const dictionaries:PdfDictEntry[][]=[[{key:"Root",value:ref(1)}],[{key:"Pages",value:ref(4)},{key:"OutputIntents",value:{kind:"array",value:[ref(2)]}}],[{key:"S",value:name("GTS_PDFX")},{key:"OutputConditionIdentifier",value:{kind:"str",value:[70,79,71,82,65,51,57]}},{key:"DestOutputProfile",value:ref(3)}]];
    if(subset==="🧾️vt")dictionaries.push([{key:"DPartRootNode",value:ref(11)}],[{key:"Parent",value:ref(10)},{key:"Start",value:ref(5)}]);
    const intent={subtype:"GTS_PDFX",conditionIdentifier:"FOGRA39",condition:null,registryName:null,info:null,profile},out=await PdfProjection.create(PDF17_SQLITE_SCHEMA,{},pdfAnnotationNumberColumns),keys:bigint[]=[];
    for(const dictionary of dictionaries)keys.push(await writePdfDictionary(out,dictionary));const intentKey=await writePdfOutputIntent(out,intent),bytes=await exportSqliteDatabase(await out.finish()),sql=Database.deserialize(bytes);
    expect(sql.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(sql.query("PRAGMA foreign_key_check").all()).toEqual([]);
    expect(sql.query("SELECT subtype,condition_identifier,condition,registry_name,info,length(profile) AS bytes FROM pdf_output_intent").get()).toEqual({subtype:"GTS_PDFX",condition_identifier:"FOGRA39",condition:null,registry_name:null,info:null,bytes:3024});
    const stored=sql.query("SELECT profile FROM pdf_output_intent").get() as {profile:Uint8Array};expect(Array.from(stored.profile)).toEqual(profile);
    const expected=[{key:"DestOutputProfile",number:3,generation:0},{key:"OutputIntents",number:2,generation:0},{key:"Pages",number:4,generation:0},{key:"Root",number:1,generation:0}];
    if(subset==="🧾️vt")expected.push({key:"DPartRootNode",number:11,generation:0},{key:"Parent",number:10,generation:0},{key:"Start",number:5,generation:0});
    expected.sort((a,b)=>a.key<b.key?-1:a.key>b.key?1:0);
    expect(sql.query("SELECT e.key,v.reference_number AS number,v.reference_generation AS generation FROM pdf_cos_dictionary_entry e JOIN pdf_cos_value v ON v.id=e.value_id WHERE v.kind='reference' ORDER BY e.key").all()).toEqual(expected.filter(row=>row.key!=="OutputIntents"));
    const reader=await PdfReader.create(await importSqliteDatabase(bytes),PDF17_SQLITE_SCHEMA,{},pdfAnnotationNumberColumns);for(const[index,key]of keys.entries())expect(await readPdfDictionary(reader,key)).toEqual(dictionaries[index]);expect(await readPdfOutputIntent(reader,intentKey)).toEqual(intent);await reader.finish();sql.close();
  }
},{timeout:30_000});
